<?php declare(strict_types=1);use Kulturhus\Verein\Inventory; ?>
<section class="card iv-receipt" data-loan-summary><div class="section-heading"><div><h2><?= e($loanActionText('Ausleihe {number}',['number'=>Inventory::number((int)$loan['number'])])) ?></h2><p><?= e($loan['purpose']) ?></p></div><button type="button" class="btn btn-outline theme-secondary iv-no-print" data-iv-print><?= e($loanActionText('Drucken / PDF speichern')) ?></button></div>
<div class="iv-stats iv-loan-facts"><div><span><?= e($loanActionText('Entleiher')) ?></span><strong><?= e($loan['contact_name']) ?></strong><?php if($canRead): ?><a href="<?= e(url(['view'=>'members','id'=>$loan['contact_id']])) ?>"><?= e($loanActionText('Mitgliederprofil öffnen')) ?></a><?php endif ?></div><div><span><?= e($loanActionText('Status')) ?></span><strong><?= e($loanActionText(Inventory::loanStateLabel($loan))) ?></strong></div><div><span><?= e($loanActionText('Zeitraum')) ?></span><strong><?= e(!empty($loan['window_start'])?Inventory::windowLocal($loan['window_start'],'d.m.Y H:i'):dateDe($loan['starts_on'])) ?> – <?= e(!empty($loan['window_end'])?Inventory::windowLocal($loan['window_end'],'d.m.Y H:i'):dateDe($loan['due_on'])) ?></strong></div><div><span><?= e($loanActionText('Aktueller Aufenthaltsort')) ?></span><strong><?= e($loan['state']==='issued'?($loan['current_place']!==''?$loan['current_place']:$loanActionText('Nicht bestätigt')):($loan['state']==='reserved'?$loanActionText('Noch am Lagerort'):$loanActionText('Siehe Bestandsübersicht'))) ?></strong></div></div>
<?php $windowStatus=$inventory->loanWindowStatus($loanId);if(array_filter($windowStatus,static fn($row)=>!$row['fits'])): ?><p class="iv-warning" role="alert" data-loan-window-shortage><?= e($loanActionText('Der aktuelle Bestand reicht für dieses Zeitfenster nicht mehr aus. Tatsächliche Schäden, Umlagerungen und verspätete Rückgaben prüfen; die Planung vor einer Ausgabe bewusst korrigieren.')) ?><?php foreach($windowStatus as$status)if(!$status['fits']): ?><span><?= e($status['name']) ?>: <?= e($loanActionText('{available} verfügbar · {requested} geplant',['available'=>(string)$status['available'],'requested'=>(string)$status['requested']])) ?></span><?php endif ?></p><?php endif ?>
<?php if(Inventory::loanOverdue($loan)): ?><p class="iv-warning"><?= e($loanActionText('Rückgabe überfällig seit {date}.',['date'=>!empty($loan['window_end'])?Inventory::windowLocal($loan['window_end'],'d.m.Y H:i'):dateDe($loan['due_on'])])) ?></p><?php endif ?>
<h3><?= e($loanActionText('Vereinbarte Gegenstände')) ?></h3><div class="iv-loan-agreed-items"><?php foreach($loan['lines']as$line): ?><article><h3><?= e($line['item_name']) ?></h3><p><?= e($line['item_code']) ?></p><dl><?php foreach(['Ausgangsort'=>$line['location_name'],'Vereinbart'=>Inventory::contentSummary($line,(int)$line['quantity'],$loanActionText)?:$line['quantity'].' '.$line['unit'],'Zurück'=>(string)$line['returned'],'Verlust'=>(string)$line['lost'],'Noch offen'=>(string)($loan['state']==='cancelled'?0:$line['quantity']-$line['returned']-$line['lost'])]as$caption=>$value): ?><div><dt><?= e($loanActionText($caption)) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach ?></dl></article><?php endforeach ?></div><p><?= nl2br(e($loan['notes'])) ?></p><div class="iv-print-signatures"><p><?= e($loanActionText('Übergeben am / von:')) ?> _______________________</p><p><?= e($loanActionText('Empfang bestätigt:')) ?> _______________________</p></div></section>
